bool FarmingOperations::validateJsonForCreation(const Json::Value &pJson, std::string &err) {
  if (pJson.isMember("id")) {
    if (!validJsonOfField(0, "id", pJson["id"], err, true))
      return false;
  }
  if (pJson.isMember("area_id")) {
    if (!validJsonOfField(1, "area_id", pJson["area_id"], err, true))
      return false;
  } else {
    err = "The area_id column cannot be null";
    return false;
  }
  if (pJson.isMember("operation_type")) {
    if (!validJsonOfField(2, "operation_type", pJson["operation_type"], err, true))
      return false;
  } else {
    err = "The operation_type column cannot be null";
    return false;
  }
  if (pJson.isMember("operation_date")) {
    if (!validJsonOfField(3, "operation_date", pJson["operation_date"], err, true))
      return false;
  } else {
    err = "The operation_date column cannot be null";
    return false;
  }
  if (pJson.isMember("operator_id")) {
    if (!validJsonOfField(4, "operator_id", pJson["operator_id"], err, true))
      return false;
  } else {
    err = "The operator_id column cannot be null";
    return false;
  }
  if (pJson.isMember("material_used")) {
    if (!validJsonOfField(5, "material_used", pJson["material_used"], err, true))
      return false;
  }
  if (pJson.isMember("status")) {
    if (!validJsonOfField(6, "status", pJson["status"], err, true))
      return false;
  } else {
    err = "The status column cannot be null";
    return false;
  }
  if (pJson.isMember("result_description")) {
    if (!validJsonOfField(7, "result_description", pJson["result_description"], err, true))
      return false;
  }
  if (pJson.isMember("review_status")) {
    if (!validJsonOfField(8, "review_status", pJson["review_status"], err, true))
      return false;
  } else {
    err = "The review_status column cannot be null";
    return false;
  }
  if (pJson.isMember("created_at")) {
    if (!validJsonOfField(9, "created_at", pJson["created_at"], err, true))
      return false;
  }
  if (pJson.isMember("updated_at")) {
    if (!validJsonOfField(10, "updated_at", pJson["updated_at"], err, true))
      return false;
  }
  return true;
}
